import React from 'react';

import clsx from 'clsx';

import PohAva from '@ui-kit/Ava';

import styles from './styles.module.less';

interface IPohodnikCardProps extends React.HTMLAttributes<HTMLDivElement> {
  header: React.ReactNode;
  subheader: string;
  url: string;
  round?: boolean;
}

const PohodnikCard: React.FC<IPohodnikCardProps> = ({
  header,
  subheader,
  url,
  round = false,
  className,
  ...rest
}) => (
  <div {...rest} className={clsx(styles.pohUserBadge, className)}>
    {round ? (
      <PohAva
        className={clsx(styles.pohUserBadgeImg, 'me-1')}
        src={url}
        width={40}
        alt={subheader}
      />
    ) : (
      <img src={url} className={styles.pohUserBadgeImg} alt="ph" />
    )}
    <div className={styles.pohUserBadgeContent}>
      <div className={styles.pohUserBadgeHeader}>{header}</div>
      <div className={styles.pohUserBadgeSubHeader}>{subheader}</div>
    </div>
  </div>
);

export default PohodnikCard;
